mapper.select:
SELECT * FROM content_comments
WHERE content_type = #{contentType} AND content_id = #{contentId}
ORDER BY created_at ASC, id ASC

SELECT c.*, (SELECT COUNT(*) FROM content_comments reply WHERE reply.parent_id = c.id AND reply.is_deleted = FALSE) AS reply_count, (SELECT COUNT(*) FROM content_comment_likes reaction WHERE reaction.comment_id = c.id) AS like_count, EXISTS(SELECT 1 FROM content_comment_likes reaction WHERE reaction.comment_id = c.id AND reaction.user_id = #{viewerId}) AS has_liked FROM content_comments c WHERE c.content_type = #{contentType} AND c.content_id = #{contentId}
AND c.parent_id = #{parentId} AND c.parent_id IS NULL
AND (c.created_at, c.id) > (#{afterCreatedAt}, #{afterId})
ORDER BY c.created_at ASC, c.id ASC LIMIT #{limit}
